        const useShape = Constants.KAMPYLE_NOTES_SHAPES.includes(shape) ? shape : Constants.KAMPYLE_NOTES_SHAPE_STANDARD;

        // Eudoxus of Cnidus ~390-340 BC Kampyle of Eudoxus:
        // x(t) = a·sec(t), y(t) = a·tan(t)·sec(t).
        // Implicit form: x⁴ = a²(x² + y²). Two asymptotic branches approach the x-axis as t → ±π/2.
