        const useShape = Constants.NEPHROID_NOTES_SHAPES.includes(shape) ? shape : Constants.NEPHROID_NOTES_SHAPE_STANDARD;

        // Philippe de la Hire ~1670 Nephroid (the 2-cusped epicycloid, kidney-shaped):
