        this._captureUndoState(`Nephroid Notes (${useShape}, a=${clampedA}, N=${clampedLength}) on ${activeSeq.name}`);

        const numRows = activeSeq.data.length;
        const totalSteps = activeSeq.length;
        let nephroidCount = 0;
