        const useShape = Constants.ENNEOID_NOTES_SHAPES.includes(shape) ? shape : Constants.ENNEOID_NOTES_SHAPE_STANDARD;

        // 9-cusped hypocycloid (enneoid): the natural 9-cusped hypocycloid (R/r = 9),
        // the natural 9-cusped cousin of the cardioid's 1 cusp, nephroid's 2 cusps,
