            [Constants.TRITRIACONTAGON_NOTES_SHAPE_STANDARD]: [Constants.TRITRIACONTAGON_NOTES_DEFAULT_T_MIN, Constants.TRITRIACONTAGON_NOTES_DEFAULT_T_MAX],
