            [Constants.HEPTATRIACONTAGON_NOTES_SHAPE_HEPTATRIACONTAGON]: [Constants.HEPTATRIACONTAGON_NOTES_HEPTATRIACONTAGON_T_MIN, Constants.HEPTATRIACONTAGON_NOTES_HEPTATRIACONTAGON_T_MAX],
