            [Constants.HECTODUOTRIACONTAGON_NOTES_SHAPE_HECTODUOTRIACONTAGON]: [Constants.HECTODUOTRIACONTAGON_NOTES_HECTODUOTRIACONTAGON_T_MIN, Constants.HECTODUOTRIACONTAGON_NOTES_HECTODUOTRIACONTAGON_T_MAX],
